document.addEventListener("DOMContentLoaded",function(){const e=document.getElementById("quadratic-form"),t=document.getElementById("quadratic-result");e&&e.addEventListener("submit",function(e){e.preventDefault();const n=Number(document.getElementById("quad-a").value),o=Number(document.getElementById("quad-b").value),d=Number(document.getElementById("quad-c").value);if(0===n)return t.textContent="Coefficient 'a' cannot be zero.",void 0;const u=o*o-4*n*d;if(u>0){const e=(-o+Math.sqrt(u))/(2*n),d=(-o-Math.sqrt(u))/(2*n);t.innerHTML=`<b>Two solutions:</b><br>x₁ = ${e.toFixed(4)}<br>x₂ = ${d.toFixed(4)}`}else if(0===u){const e=-o/(2*n);t.innerHTML=`<b>One solution:</b><br>x = ${e.toFixed(4)}`}else t.innerHTML="No real solutions (D &lt; 0)"})});